    const msg = `${totalFlights} flights scraped for ${todayStr} + ${tomorrowStr}`;
    console.log(`[Guernsey Live] Background prefetch complete: ${msg}`);
    await logSchedulerEvent('guernsey_live', 'prefetch', msg);
  } catch (err) {
