          try { await scheduleNextScrape(); } catch {
            setTimeout(() => scheduleNextScrape().catch(e => console.error('[Guernsey Live] Fatal retry failed:', e)), 5 * 60 * 1000);
          }
        }
      }, sleepMs);
    }
  }
}

